// Compiles every Kotlin example in the README and docs/ (generated by ci/doc-snippets.py) against the published
// artifacts, on the oldest Kotlin PassKi supports.
plugins {
    kotlin("multiplatform") version "2.2.21"
    kotlin("plugin.compose") version "2.2.21"
    id("org.jetbrains.compose") version "1.10.3"
}

val passkiVersion = gradle.extra["passkiVersion"] as String

kotlin {
    jvm()
    sourceSets {
        jvmMain {
            kotlin.srcDir(layout.buildDirectory.dir("generated/snippets"))
            dependencies {
                implementation("com.alirezaiyan.passki:passki:$passkiVersion")
                implementation("com.alirezaiyan.passki:passki-compose:$passkiVersion")
                implementation("com.alirezaiyan.passki:passki-demo:$passkiVersion")
                implementation("com.alirezaiyan.passki:passki-test:$passkiVersion")
                implementation(kotlin("test-junit")) // kotlin.test.Test for the server-test example

                implementation("org.jetbrains.compose.runtime:runtime:1.10.3")
                implementation("org.jetbrains.compose.material3:material3:1.10.0-alpha05")
            }
        }
    }
}
